'use strict';

const { execFile } = require('child_process');
const { promisify } = require('util');
const {
  createCh9329Input,
  createNanoKvmInput,
  listDevices,
  probeInputDevice
} = require('..');

const execFileAsync = promisify(execFile);

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseArgs(argv) {
  const options = {
    ch9329Port: process.env.CH9329_PORT || '',
    nanoKvmPort: process.env.NANOKVM_PORT || '',
    stepDx: Number(process.env.RELATIVE_COMPARE_DX || 40),
    stepDy: Number(process.env.RELATIVE_COMPARE_DY || 0),
    repeat: Number(process.env.RELATIVE_COMPARE_REPEAT || 8),
    delayMs: Number(process.env.RELATIVE_COMPARE_DELAY_MS || 35),
    settleMs: Number(process.env.RELATIVE_COMPARE_SETTLE_MS || 250),
    pauseMs: Number(process.env.RELATIVE_COMPARE_PAUSE_MS || 800),
    warpStart: process.env.RELATIVE_COMPARE_WARP_START !== '0'
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = argv[index + 1];
    if (arg === '--ch9329-port' && next) {
      options.ch9329Port = next;
      index += 1;
    } else if (arg === '--nanokvm-port' && next) {
      options.nanoKvmPort = next;
      index += 1;
    } else if (arg === '--dx' && next) {
      options.stepDx = Number(next);
      index += 1;
    } else if (arg === '--dy' && next) {
      options.stepDy = Number(next);
      index += 1;
    } else if (arg === '--repeat' && next) {
      options.repeat = Number(next);
      index += 1;
    } else if (arg === '--delay' && next) {
      options.delayMs = Number(next);
      index += 1;
    } else if (arg === '--no-warp') {
      options.warpStart = false;
    }
  }

  if (!Number.isFinite(options.stepDx)) options.stepDx = 40;
  if (!Number.isFinite(options.stepDy)) options.stepDy = 0;
  if (!Number.isFinite(options.repeat) || options.repeat <= 0) options.repeat = 8;
  if (!Number.isFinite(options.delayMs) || options.delayMs < 0) options.delayMs = 35;

  return options;
}

async function getCursorPosFromSystem() {
  if (process.platform !== 'darwin') {
    throw new Error(`cursor sampling is currently implemented for macOS only, got ${process.platform}`);
  }

  const { stdout } = await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'let p = NSEvent.mouseLocation',
      'let frame = NSScreen.screens.first?.frame ?? .zero',
      'print("\\(Int(p.x)),\\(Int(frame.height - p.y))")'
    ].join('\n')
  ]);
  const [x, y] = stdout.trim().split(',').map((value) => Number(value));
  if (!Number.isFinite(x) || !Number.isFinite(y)) {
    throw new Error(`invalid cursor output: ${stdout}`);
  }
  return { x, y };
}

async function warpCursorToMainScreenCenter() {
  if (process.platform !== 'darwin') {
    return;
  }

  await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'import CoreGraphics',
      'let frame = NSScreen.screens.first?.frame ?? .zero',
      'let point = CGPoint(x: frame.midX, y: frame.midY)',
      'CGWarpMouseCursorPosition(point)',
      'CGAssociateMouseAndMouseCursorPosition(boolean_t(1))'
    ].join('\n')
  ]);
}

async function detectPort(kind, explicitPort) {
  if (explicitPort) {
    const result = await probeInputDevice(explicitPort, {
      kind,
      probeTimeoutMs: 1500,
      logger: null
    });
    if (!result.available) {
      throw new Error(`${kind} probe failed on ${explicitPort}: ${result.reason || 'unknown error'}`);
    }
    return result.portPath;
  }

  const devices = await listDevices();
  for (const device of devices.filter((item) => item.isUsbLike)) {
    const result = await probeInputDevice(device.path, {
      kind,
      probeTimeoutMs: 1500,
      logger: null
    });
    if (result.available) {
      return result.portPath;
    }
  }

  throw new Error(`no available ${kind} port found`);
}

function createInput(kind, portPath) {
  if (kind === 'ch9329') {
    return createCh9329Input({
      portPath,
      baudRate: 9600,
      logger: null
    });
  }

  return createNanoKvmInput({
    portPath,
    baudRate: 57600,
    logger: null
  });
}

async function runRelativeStream(input, dx, dy, repeat, delayMs) {
  for (let index = 0; index < repeat; index += 1) {
    await input._debug.sendRelativeMove(dx, dy);
    if (delayMs > 0) {
      await sleep(delayMs);
    }
  }
}

async function measureCase(input, kind, portPath, label, dx, dy, options) {
  const before = await getCursorPosFromSystem();
  await runRelativeStream(input, dx, dy, options.repeat, options.delayMs);
  await sleep(options.settleMs);
  const after = await getCursorPosFromSystem();

  return {
    kind,
    portPath,
    label,
    sent: {
      dx,
      dy,
      repeat: options.repeat,
      totalDx: dx * options.repeat,
      totalDy: dy * options.repeat,
      delayMs: options.delayMs
    },
    before,
    after,
    actual: {
      dx: after.x - before.x,
      dy: after.y - before.y
    }
  };
}

async function measureDevice(kind, portPath, options) {
  if (options.warpStart) {
    await warpCursorToMainScreenCenter();
    await sleep(options.settleMs);
  }

  const input = createInput(kind, portPath);
  await input.connect();
  try {
    const forward = await measureCase(
      input,
      kind,
      portPath,
      'forward',
      options.stepDx,
      options.stepDy,
      options
    );
    await sleep(options.pauseMs);
    const backward = await measureCase(
      input,
      kind,
      portPath,
      'return',
      -options.stepDx,
      -options.stepDy,
      options
    );

    return {
      kind,
      portPath,
      forward,
      backward,
      roundTrip: {
        dx: forward.actual.dx + backward.actual.dx,
        dy: forward.actual.dy + backward.actual.dy
      }
    };
  } finally {
    await input.disconnect();
  }
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  const ch9329Port = await detectPort('ch9329', options.ch9329Port);
  const nanoKvmPort = await detectPort('nanokvm', options.nanoKvmPort);

  console.log(JSON.stringify({
    options,
    devices: {
      ch9329: ch9329Port,
      nanokvm: nanoKvmPort
    }
  }, null, 2));

  const results = [];
  for (const [kind, portPath] of [
    ['ch9329', ch9329Port],
    ['nanokvm', nanoKvmPort]
  ]) {
    console.log(`[relative-compare] measuring ${kind} on ${portPath}`);
    const result = await measureDevice(kind, portPath, options);
    results.push(result);
    console.log(JSON.stringify(result, null, 2));
    await sleep(options.pauseMs);
  }

  console.log(JSON.stringify({ results }, null, 2));
}

main().catch((error) => {
  console.error('[relative-compare] failed:', error);
  process.exitCode = 1;
});
